import{_ as p,W as i,s as o,u as d,ah as c,I as t,w as s,Z as e,A as l}from"./chunks/framework.ChbOY6p5.js";import"./chunks/theme.B6FFP-dx.js";const f=JSON.parse('{"title":"在 Linux 上使用 Multitail | LCTT x X-CMD","titleTemplate":false,"description":"在 Linux 上使用 Multitail | LCTT (201912) | X-CMD","frontmatter":{"pageClass":"x-blog","head":[["meta",{"name":"og:title","content":"在 Linux 上使用 Multitail | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"在 Linux 上使用 Multitail | LCTT (201912) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201912/20191017 Using multitail on Linux","title":"在 Linux 上使用 Multitail","tag":"201912"},"relativePath":"201912/20191017 Using multitail on Linux.md","filePath":"[post].md"}'),u={name:"201912/20191017 Using multitail on Linux.md"};function r(m,a,h,g,b,x){const n=i("Link");return d(),o("div",null,[a[15]||(a[15]=c(`<h1 id="在-linux-上使用-multitail" tabindex="-1">在 Linux 上使用 Multitail <a class="header-anchor" href="#在-linux-上使用-multitail" aria-label="Permalink to 在 Linux 上使用 Multitail">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/201912/05/053423mpnrn95hqqknzheq.jpg" alt=""></p><p>当你想同时查看多个文件（尤其是日志文件）的活动时，<code>multitail</code> 命令会非常有用。它的工作方式类似于多窗口形式的 <code>tail -f</code> 命令。也就是说，它显示这些文件的底部和添加的新行。虽然通常使用简单，但是 <code>multitail</code> 提供了一些命令行和交互式选项，在开始使用它之前，你应该了解它们。</p><h3 id="基本-multitail-使用" tabindex="-1">基本 multitail 使用 <a class="header-anchor" href="#基本-multitail-使用" aria-label="Permalink to 基本 multitail 使用">​</a></h3><p><code>multitail</code> 的最简单用法是在命令行中列出你要查看的文件名称。此命令水平分割屏幕（即顶部和底部），并显示每个文件的底部以及更新。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ multitail /var/log/syslog /var/log/dmesg</span></span></code></pre></div><p>显示内容将像这样拆分：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>+-----------------------+</span></span>
<span class="line"><span>|                       |</span></span>
<span class="line"><span>|                       |</span></span>
<span class="line"><span>+-----------------------|</span></span>
<span class="line"><span>|                       |</span></span>
<span class="line"><span>|                       |</span></span>
<span class="line"><span>+-----------------------+</span></span></code></pre></div><p>每个文件都有一行显示该文件的文件编号（从 00 开始）、文件名、文件大小、最新内容的添加日期和时间。每个文件将被分配一半空间，而不论它的大小和活动情况。比如：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>content lines from my1.log</span></span>
<span class="line"><span>more content</span></span>
<span class="line"><span>more lines</span></span>
<span class="line"><span></span></span>
<span class="line"><span>00] my1.log                                    59KB - 2019/10/14 12:12:09</span></span>
<span class="line"><span>content lines from my2.log</span></span>
<span class="line"><span>more content</span></span>
<span class="line"><span>more lines</span></span>
<span class="line"><span></span></span>
<span class="line"><span>01] my2.log                                   120KB - 2019/10/14 14:22:29</span></span></code></pre></div><p>请注意，如果你要求 <code>multitail</code> 显示非文本文件或者你无权查看的文件，它不会报错。你只是看不到内容。</p><p>你还可以使用通配符指定要查看的文件：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ multitail my*.log</span></span></code></pre></div><p>要记住的一件事是，<code>multitail</code> 将平均分割屏幕。如果指定的文件太多，那么除非你采取额外的步骤查看之后的文件（参考下面的滚动选项），否则你将只会看到前面 7 个文件的前面几行。确切的结果取决于终端窗口中有多少行可用。</p><p>按 <code>q</code> 退出 <code>multitail</code> 并返回到正常的屏幕视图。</p><h3 id="分割屏幕" tabindex="-1">分割屏幕 <a class="header-anchor" href="#分割屏幕" aria-label="Permalink to 分割屏幕">​</a></h3><p>如果你愿意，<code>multitail</code> 也可以垂直分割你的终端窗口（即，左和右）。为此，请使用 <code>-s</code> 选项。如果指定了三个文件，那么屏幕右侧的窗口将会水平分隔。四个文件的话，你将拥有四个大小相等的窗口。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>+-----------+-----------+     +-----------+-----------+     +-----------+-----------+</span></span>
<span class="line"><span>|           |           |     |           |           |     |           |           |</span></span>
<span class="line"><span>|           |           |     |           |           |     |           |           |</span></span>
<span class="line"><span>|           |           |     |           +-----------+     +-----------+-----------+</span></span>
<span class="line"><span>|           |           |     |           |           |     |           |           |</span></span>
<span class="line"><span>|           |           |     |           |           |     |           |           |</span></span>
<span class="line"><span>+-----------+-----------+     +-----------+-----------+     +-----------+-----------+</span></span>
<span class="line"><span>         2 个文件                       3 个文件                       4 个文件</span></span></code></pre></div><p>如果要将屏幕分为三列，请使用 <code>multitail -s 3 file1 file2 file3</code>。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>+-------+-------+-------+</span></span>
<span class="line"><span>|       |       |       |</span></span>
<span class="line"><span>|       |       |       |</span></span>
<span class="line"><span>|       |       |       |</span></span>
<span class="line"><span>|       |       |       |</span></span>
<span class="line"><span>|       |       |       |</span></span>
<span class="line"><span>+-------+-------+-------+</span></span>
<span class="line"><span>  3 个文件带上 -s 3 选项</span></span></code></pre></div><h3 id="滚动" tabindex="-1">滚动 <a class="header-anchor" href="#滚动" aria-label="Permalink to 滚动">​</a></h3><p>你可以上下滚动文件，但是需要按下 <code>b</code> 弹出选择菜单，然后使用向上和向下箭头按钮选择要滚动浏览的文件。然后按下回车键。然后，你可以再次使用向上和向下箭头在放大的区域中滚动浏览各行。完成后按下 <code>q</code> 返回正常视图。</p><h3 id="获得帮助" tabindex="-1">获得帮助 <a class="header-anchor" href="#获得帮助" aria-label="Permalink to 获得帮助">​</a></h3><p>在 <code>multitail</code> 中按下 <code>h</code> 将打开一个帮助菜单，其中描述了一些基本操作，但是手册页提供了更多信息，如果莫想了解更多有关使用此工具的信息，请仔细阅读。</p><p>默认情况下，你的系统上不会安装 <code>multitail</code>，但是使用 <code>apt-get</code> 或 <code>yum</code> 可以使你轻松安装。该工具提供了许多功能，不过它是基于字符显示的，窗口边框只是 <code>q</code> 和 <code>x</code> 的字符串组成的。当你需要关注文件更新时，它非常方便。</p><hr>`,26)),t("p",null,[a[1]||(a[1]=s("via: ")),e(n,{href:"https://www.networkworld.com/article/3445228/using-multitail-on-linux.html"},{default:l(()=>a[0]||(a[0]=[s("https://www.networkworld.com/article/3445228/using-multitail-on-linux.html")])),_:1})]),t("p",null,[a[6]||(a[6]=s("作者：")),e(n,{href:"https://www.networkworld.com/author/Sandra-Henry_Stocker/"},{default:l(()=>a[2]||(a[2]=[s("Sandra Henry-Stocker")])),_:1}),a[7]||(a[7]=s(" 选题：")),e(n,{href:"https://github.com/lujun9972"},{default:l(()=>a[3]||(a[3]=[s("lujun9972")])),_:1}),a[8]||(a[8]=s(" 译者：")),e(n,{href:"https://github.com/geekpi"},{default:l(()=>a[4]||(a[4]=[s("geekpi")])),_:1}),a[9]||(a[9]=s(" 校对：")),e(n,{href:"https://github.com/wxy"},{default:l(()=>a[5]||(a[5]=[s("wxy")])),_:1})]),t("p",null,[a[12]||(a[12]=s("本文由 ")),e(n,{href:"https://github.com/LCTT/TranslateProject"},{default:l(()=>a[10]||(a[10]=[s("LCTT")])),_:1}),a[13]||(a[13]=s(" 原创编译，")),e(n,{href:"https://linux.cn/"},{default:l(()=>a[11]||(a[11]=[s("Linux中国")])),_:1}),a[14]||(a[14]=s(" 荣誉推出"))])])}const C=p(u,[["render",r]]);export{f as __pageData,C as default};
